WITH ranked AS (SELECT * FROM (SELECT *, RANK() OVER (PARTITION BY promo_code, channel ORDER BY discount_pct DESC) AS rank_in_group FROM promotions) t WHERE rank_in_group = 1) SELECT CASE WHEN discount_pct >= 0.35 THEN 'LARGE' ELSE 'SMALL' END AS discount_pct_tier, COUNT(*) FILTER (WHERE channel = 'web') AS web_rows, ROUND(SUM(discount_pct) / NULLIF(COUNT(CASE WHEN channel = 'store' THEN 1 END), 0), 2) AS discount_pct_per_store, ROUND(SUM(discount_pct) / NULLIF(COUNT(CASE WHEN channel = 'store' THEN 1 END), 0), 2) AS discount_pct_per_store_2 FROM ranked GROUP BY CUBE (CASE WHEN discount_pct >= 0.35 THEN 'LARGE' ELSE 'SMALL' END) ORDER BY discount_pct_per_store_2 DESC
